attern":"^agt_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"}},"additionalProperties":false}]}},"additionalProperties":false}},"required":["schemaVersion","installationId","operationRef","recordVersion","canonicalRequest","requestDigest","actorId","auditId","committedAt","kind","subjectKind","subjectRef","sourceOperationRef","sourceRecordVersion","profile","configuration"],"additionalProperties":false},{"type":"object","properties":{"schemaVersion":{"type":"integer","const":1},"installationId":{"type":"string","pattern":"^ins_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"},"operationRef":{"type":"string","pattern":"^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"},"recordVersion":{"type":"integer","minimum":1,"maximum":9007199254740991},"canonicalRequest":{"type":"string","minLength":1,"maxLength":8192},"requestDigest":{"type":"string","pattern":"^sha256:[0-9a-f]{64}$"},"actorId":{"type":"string","minLength":1,"maxLength":200,"pattern":"^[A-Za-z0-9._:/-]+$"},"auditId":{"type":"string","pattern":"^aud_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"},"committedAt":{"type":"string","pattern":"^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\\.[0-9]{3}Z$"},"kind":{"type":"string","const":"service-withdraw"},"subjectKind":{"type":"string","const":"service"},"subjectRef":{"type":"string","pattern":"^runtime-service/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"}},"required":["schemaVersion","installationId","operationRef","recordVersion","canonicalRequest","requestDigest","actorId","auditId","committedAt","kind","subjectKind","subjectRef"],"additionalProperties":false}]}$record$::jsonb) THEN
   RAISE EXCEPTION 'runtime service trust closed shape invalid' USING ERRCODE='23514';
 END IF;
 IF NEW.canonical_request IS DISTINCT FROM occ.runtime_authority_canonical(request)
 OR NEW.request_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(NEW.canonical_request,'UTF8')),'hex')
 OR NEW.record->>'canonicalRequest' IS DISTINCT FROM NEW.canonical_request
 OR NEW.record->>'requestDigest' IS DISTINCT FROM NEW.request_digest
 OR NEW.record->>'installationId' IS DISTINCT FROM NEW.installation_id
 OR NEW.record->>'subjectKind' IS DISTINCT FROM NEW.subject_kind
 OR NEW.record->>'subjectRef' IS DISTINCT FROM NEW.subject_ref
 OR (NEW.record->>'recordVersion')::bigint IS DISTINCT FROM NEW.record_version
 OR NEW.record->>'operationRef' IS DISTINCT FROM NEW.operation_ref
 OR NEW.record->>'actorId' IS DISTINCT FROM NEW.actor_id
 OR NEW.record->>'auditId' IS DISTINCT FROM NEW.audit_id
 OR (NEW.record->>'committedAt')::timestamptz IS DISTINCT FROM NEW.committed_at
 OR request->>'operationRef' IS DISTINCT FROM NEW.operation_ref
 OR request->>'kind' IS DISTINCT FROM NEW.record->>'kind'
 OR (request->>'expectedVersion')::bigint IS DISTINCT FROM nullif(NEW.record_version-1,0)
 OR NOT EXISTS(SELECT 1 FROM occ.iam_identities WHERE id=NEW.actor_id AND kind='principal' AND namespace_id IS NULL)
 THEN RAISE EXCEPTION 'runtime service trust immutable attribution invalid' USING ERRCODE='23514'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('runtime-service-trust-operation:'||NEW.operation_ref,0));
 IF NEW.record->>'kind'='service-admit' THEN
  PERFORM pg_advisory_xact_lock(hashtextextended('runtime-service-trust-subject:'||NEW.installation_id||':source:'||(request->>'sourceRef'),0));
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('runtime-service-trust-subject:'||NEW.installation_id||':'||NEW.subject_kind||':'||NEW.subject_ref,0));
 SELECT * INTO previous FROM occ.runtime_service_trust_records WHERE installation_id=NEW.installation_id AND subject_kind=NEW.subject_kind AND subject_ref=NEW.subject_ref ORDER BY record_version DESC LIMIT 1;
 IF NEW.record_version<>coalesce(previous.record_version,0)+1 THEN RAISE EXCEPTION 'runtime service trust version conflict' USING ERRCODE='23514'; END IF;
 IF NEW.subject_kind='source' THEN
  IF request->>'sourceRef' IS DISTINCT FROM NEW.subject_ref THEN RAISE EXCEPTION 'runtime source owner invalid' USING ERRCODE='23514'; END IF;
 ELSE
  IF request->>'serviceIdentityRef' IS DISTINCT FROM (CASE WHEN NEW.record_version=1 AND NEW.record->>'kind'='service-admit' THEN NULL ELSE NEW.subject_ref END) THEN RAISE EXCEPTION 'runtime service owner invalid' USING ERRCODE='23514'; END IF;
 END IF;
 IF NEW.record->>'kind' LIKE '%-withdraw' AND NEW.record_version=1 THEN RAISE EXCEPTION 'runtime withdrawal has no predecessor' USING ERRCODE='23514'; END IF;
 IF NEW.record->>'kind'='source-admit' THEN
  source_value:=NEW.record->'source';
  IF source_value->>'sourceRef' IS DISTINCT FROM NEW.subject_ref OR NEW.record->>'sourceConfigurationDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(occ.runtime_authority_canonical(source_value),'UTF8')),'hex') THEN RAISE EXCEPTION 'runtime source digest invalid' USING ERRCODE='23514'; END IF;
 ELSIF NEW.record->>'kind'='service-admit' THEN
  profile:=NEW.record->'profile'; configuration:=NEW.record->'configuration';
  source_value:=profile-'operationPolicy'-'sourceConfigurationDigest'-'peerSPIFFEId';
  SELECT * INTO source_row FROM occ.runtime_service_trust_records WHERE installation_id=NEW.installation_id AND subject_kind='source' AND subject_ref=request->>'sourceRef' ORDER BY record_version DESC LIMIT 1;
  IF source_row.record->>'kind' IS DISTINCT FROM 'source-admit'
   OR source_row.operation_ref IS DISTINCT FROM NEW.record->>'sourceOperationRef'
   OR source_row.record_version IS DISTINCT FROM (NEW.record->>'sourceRecordVersion')::bigint
   OR source_row.record->'source' IS DISTINCT FROM source_value
   OR source_row.record->>'sourceConfigurationDigest' IS DISTINCT FROM profile->>'sourceConfigurationDigest'
   OR profile->>'sourceRef' IS DISTINCT FROM request->>'sourceRef'
   OR profile->>'peerSPIFFEId' IS DISTINCT FROM request->>'peerSPIFFEId'
   OR profile->>'operationPolicy' IS DISTINCT FROM coalesce(request->>'operationPolicy','read-operation-only-v1')
   OR left(profile->>'peerSPIFFEId',length('spiffe://'||(profile->>'trustDomain')||'/')) IS DISTINCT FROM 'spiffe://'||(profile->>'trustDomain')||'/'
   OR configuration->>'installationId' IS DISTINCT FROM NEW.installation_id
   OR configuration->>'serviceIdentityRef' IS DISTINCT FROM NEW.subject_ref
   OR (configuration->>'configurationVersion')::bigint IS DISTINCT FROM NEW.record_version
   OR configuration->>'role' IS DISTINCT FROM 'lifecycle-authority'
   OR configuration->'allowedScope' IS DISTINCT FROM jsonb_build_object('kind','agent','installationId',NEW.installation_id,'namespaceId',request->>'namespaceId','agentId',request->>'agentId')
   OR configuration->>'serviceTrustProfileDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(occ.runtime_authority_canonical(profile),'UTF8')),'hex')
   OR configuration->>'trustRootsRef' IS DISTINCT FROM profile->>'trustRootsRef'
   OR configuration->>'verifierProfileRef' IS DISTINCT FROM profile->>'verifierProfileRef'
   OR configuration->>'permittedRecipientRef' IS DISTINCT FROM profile->>'recipientRef'
   OR NOT EXISTS(SELECT 1 FROM occ.agents a JOIN occ.namespaces n ON n.id=a.namespace_id WHERE n.deleted_at IS NULL AND n.id=request->>'namespaceId' AND a.id=request->>'agentId')
  THEN RAISE EXCEPTION 'runtime service source or scope invalid' USING ERRCODE='23514'; END IF;
 END IF;
 IF source_value IS NOT NULL AND (
  source_value->>'ownSPIFFEId' IS DISTINCT FROM source_value->>'recipientSPIFFEId'
  OR left(source_value->>'ownSPIFFEId',length('spiffe://'||(source_value->>'trustDomain')||'/')) IS DISTINCT FROM 'spiffe://'||(source_value->>'trustDomain')||'/'
  OR source_value->>'workloadApiSocketPath' ~ '(^|/)[.]{1,2}(/|$)'
 ) THEN RAISE EXCEPTION 'runtime technical source invalid' USING ERRCODE='23514'; END IF;
 SELECT * INTO event FROM occ.audit_events WHERE id=NEW.audit_id;
 meta:=event.details->'__occAuditMetadata';
 IF event.id IS NULL OR event.kind<>'mutation' OR event.outcome<>'success' OR event.actor_id<>NEW.actor_id
 OR event.occurred_at<>NEW.committed_at OR event.namespace_id IS NOT NULL OR event.resource_kind<>'installation' OR event.resource_id<>NEW.installation_id
 OR event.action IS DISTINCT FROM 'openclaw.runtime-service-trust.'||(NEW.record->>'kind')
 OR meta->>'source' IS DISTINCT FROM 'occ' OR meta->>'schemaVersion' IS DISTINCT FROM '1'
 OR meta#>>'{actor,principalId}' IS DISTINCT FROM NEW.actor_id
 OR NOT EXISTS(SELECT 1 FROM occ.iam_identities i WHERE i.id=NEW.actor_id AND i.kind='principal' AND i.namespace_id IS NULL AND i.issuer=meta#>>'{actor,issuer}' AND i.subject=meta#>>'{actor,subject}')
 OR jsonb_typeof(event.details->'checks') IS DISTINCT FROM 'array' OR jsonb_array_length(event.details->'checks') IS DISTINCT FROM 1
 OR event.details#>'{checks,0,request}' IS DISTINCT FROM meta->'authorization'
 OR event.details#>'{checks,0,decision,allowed}' IS DISTINCT FROM 'true'::jsonb
 OR event.details#>>'{checks,0,decision,driverId}' IS DISTINCT FROM meta->>'iamDriverId'
 OR jsonb_typeof(event.details#>'{checks,0,decision,evidence}') IS DISTINCT FROM 'object'
 OR meta#>'{authorization}' IS DISTINCT FROM jsonb_build_object('principalId',NEW.actor_id,'action','administer','resource',jsonb_build_object('kind','installation','id',NEW.installation_id))
 OR coalesce(meta->>'iamDriverId','')='' OR coalesce(meta->>'requestId','')='' OR coalesce(meta->>'admissionDecisionId','')=''
 OR event.details->>'operationRef' IS DISTINCT FROM NEW.operation_ref OR event.details->>'subjectRef' IS DISTINCT FROM NEW.subject_ref OR (event.details->>'recordVersion')::bigint IS DISTINCT FROM NEW.record_version OR event.details->>'requestDigest' IS DISTINCT FROM NEW.request_digest
 THEN RAISE EXCEPTION 'runtime service mandatory audit invalid' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END;
$$;
